algorithms.pseudocode:
Given axioms Ax over universe U:
1. models = {x in U | forall P in Ax, P(x)}
2. closure = {P | forall x in models, P(x)}
3. return closure

algorithms.code:
def axiom_closure(axioms, all_predicates, universe):
    m = frozenset(x for x in universe if all(ax(x) for ax in axioms))
    return [p for p in all_predicates if all(p(x) for x in m)]

def genome_distance(t1, t2):
    c1 = t1.axiom_closure()
    c2 = t2.axiom_closure()
    return len(c1.symmetric_difference(c2))

def find_mutation_path(t1, t2):
    diff = t1.axiom_indices ^ t2.axiom_indices
    path, current = [t1], set(t1.axiom_indices)
    for ax in sorted(diff):
        if ax in t2.axiom_indices: current.add(ax)
        else: current.discard(ax)
        path.append(TheoryGenome(frozenset(current), t1.universe, t1.predicate_list))
    return path
